import { precacheAndRoute, createHandlerBoundToURL } from 'workbox-precaching'
import { NavigationRoute, registerRoute } from 'workbox-routing'

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || [])

// Serve cached index.html for all navigation requests (SPA deep links)
const handler = createHandlerBoundToURL('/index.html')
const navigationRoute = new NavigationRoute(handler)
registerRoute(navigationRoute)

// Activate new SW immediately — don't wait for old clients to send SKIP_WAITING.
// This ensures updates are applied even when the old cached JS doesn't trigger it.
self.addEventListener('install', () => self.skipWaiting())

self.addEventListener('message', (event) => {
    if (event.data && event.data.type === 'SKIP_WAITING') {
        self.skipWaiting()
    }
})

self.addEventListener('push', function (event) {
    if (event.data) {
        try {
            const data = event.data.json()
            const title = data.title || 'TIX Benachrichtigung'
            const options = {
                body: data.body,
                icon: '/pwa-192x192.png',
                badge: '/masked-icon.png',
                data: {
                    url: data.url || '/'
                }
            }
            event.waitUntil(self.registration.showNotification(title, options))
        } catch (e) {
            console.error('Error parsing push data:', e)
            event.waitUntil(
                self.registration.showNotification('TIX', {
                    body: event.data.text(),
                    icon: '/pwa-192x192.png'
                })
            )
        }
    }
})

self.addEventListener('notificationclick', function (event) {
    event.notification.close()

    const urlToOpen = new URL(event.notification.data.url, self.location.origin).href

    event.waitUntil(
        clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
            // Check if there is already a window/tab open with the target URL
            let matchingClient = null;
            let anyClient = null;

            for (let i = 0; i < windowClients.length; i++) {
                const client = windowClients[i];
                if (client.url === urlToOpen) {
                    matchingClient = client;
                    break;
                }
                if (!anyClient) anyClient = client; // Keep first available client as fallback
            }

            // If we have an exact match, focus it and tell it to refresh
            if (matchingClient) {
                matchingClient.postMessage({ type: 'TICKET_UPDATE', url: event.notification.data.url });
                return matchingClient.focus();
            }
            // If we have a window open but different URL, focus it and navigate
            else if (anyClient) {
                return anyClient.focus().then((c) => c.navigate(urlToOpen));
            }
            // Otherwise open a new window
            else {
                return clients.openWindow(urlToOpen);
            }
        })
    )
})
